import{_ as n,C as i,o as e,c as s,a2 as l,b as r,w as a,a as f,E as g,a3 as x}from"./chunks/framework.Crpw6aS5.js";const B=JSON.parse('{"title":"主题索引","description":"巴菲特致股东信70年核心主题全覆盖——基于全文翻译重新归纳","frontmatter":{"title":"主题索引","description":"巴菲特致股东信70年核心主题全覆盖——基于全文翻译重新归纳"},"headers":[],"relativePath":"02_concepts/index.md","filePath":"02_concepts/index.md"}'),y={name:"02_concepts/index.md"};function o(h,t,E,c,A,p){const d=i("Mermaid");return e(),s("div",null,[t[1]||(t[1]=l('<h1 id="主题索引" tabindex="-1">主题索引 <a class="header-anchor" href="#主题索引" aria-label="Permalink to &quot;主题索引&quot;">​</a></h1><p>按主题分类阅读巴菲特致股东信的核心思想，提炼70年投资智慧的精华。</p><blockquote><p>本索引基于1956-2025年全部70年股东信<strong>全文翻译</strong>重新归纳。区别于传统索引，本版本覆盖了合伙基金时期（1956-1969）的投资方法论，并新增了全文翻译中发现的重要主题：递延税复利、透视盈利、通胀绦虫、所罗门危机等。</p></blockquote><hr><h2 id="投资哲学-5个核心" tabindex="-1">投资哲学（5个核心） <a class="header-anchor" href="#投资哲学-5个核心" aria-label="Permalink to &quot;投资哲学（5个核心）&quot;">​</a></h2><p>投资哲学是巴菲特思想体系的根基。五个概念构成了价值投资的完整框架。</p><table tabindex="0"><thead><tr><th style="text-align:left;">主题</th><th style="text-align:left;">核心要义</th><th style="text-align:left;">首次出现</th><th style="text-align:left;">必读年份</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/02_concepts/intrinsic-value.html">内在价值 Intrinsic Value</a></td><td style="text-align:left;">企业真正值多少钱，是唯一评估标准</td><td style="text-align:left;">1962</td><td style="text-align:left;">1994, 2007, 2010</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/moat.html">护城河 Moat</a></td><td style="text-align:left;">竞争优势的宽度与持久度</td><td style="text-align:left;">1991</td><td style="text-align:left;">1993, 1999, 2007, 2014</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/safety-margin.html">安全边际 Margin of Safety</a></td><td style="text-align:left;">用折扣价格买好资产</td><td style="text-align:left;">1962</td><td style="text-align:left;">1993, 1997, 2007</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/compounding.html">复利 Compounding</a></td><td style="text-align:left;">时间是伟大事业的朋友</td><td style="text-align:left;">1963</td><td style="text-align:left;">1965, 1993, 2013, 2023</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/accounting-earnings.html">真实盈利 vs GAAP盈利</a></td><td style="text-align:left;">为什么会计盈利不等于真实盈利</td><td style="text-align:left;">1980</td><td style="text-align:left;">1980, 1983, 2019</td></tr></tbody></table><h2 id="商业逻辑-4个核心" tabindex="-1">商业逻辑（4个核心） <a class="header-anchor" href="#商业逻辑-4个核心" aria-label="Permalink to &quot;商业逻辑（4个核心）&quot;">​</a></h2><p>伯克希尔的商业模式独步全球。理解保险浮存金的秘密、承保纪律的意义、资本配置的艺术、递延税复利的优势，才能真正看懂巴菲特在做什么。</p><table tabindex="0"><thead><tr><th style="text-align:left;">主题</th><th style="text-align:left;">核心要义</th><th style="text-align:left;">首次出现</th><th style="text-align:left;">必读年份</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/02_concepts/insurance-float.html">保险浮存金 Insurance Float</a></td><td style="text-align:left;">伯克希尔的秘密引擎，先收后付模式</td><td style="text-align:left;">1967</td><td style="text-align:left;">1967, 2005, 2006, 2017</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/underwriting-discipline.html">承保纪律 Underwriting Discipline</a></td><td style="text-align:left;">不做价格战，守住底线</td><td style="text-align:left;">1974</td><td style="text-align:left;">2001, 2004, 2017</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/capital-allocation.html">资本配置 Capital Allocation</a></td><td style="text-align:left;">把每一分钱用在刀刃上，CEO的核心职责</td><td style="text-align:left;">1986</td><td style="text-align:left;">1986, 2012, 2020</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/deferred-tax.html">递延税复利 Deferred Tax Compounding</a></td><td style="text-align:left;">未实现利得递延纳税，复利的隐形翅膀</td><td style="text-align:left;">1989</td><td style="text-align:left;">1989, 2000, 2019</td></tr></tbody></table><h2 id="投资方法论-5个核心" tabindex="-1">投资方法论（5个核心） <a class="header-anchor" href="#投资方法论-5个核心" aria-label="Permalink to &quot;投资方法论（5个核心）&quot;">​</a></h2><p>投资是一场思维方式的较量。知道自己懂什么、保持独立思考、理解真正的风险、掌握透视盈利、用好回购工具——这些是巴菲特区别于普通投资者的核心能力。</p><table tabindex="0"><thead><tr><th style="text-align:left;">主题</th><th style="text-align:left;">核心要义</th><th style="text-align:left;">首次出现</th><th style="text-align:left;">必读年份</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/02_concepts/circle-of-competence.html">能力圈 Circle of Competence</a></td><td style="text-align:left;">知道边界比知道多少更重要</td><td style="text-align:left;">1962</td><td style="text-align:left;">1996, 1999, 2017</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/contrarian.html">逆向思维 Contrarian</a></td><td style="text-align:left;">别人恐惧时贪婪</td><td style="text-align:left;">1964</td><td style="text-align:left;">1987, 2008, 2009, 2020</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/risk.html">风险与回报 Risk</a></td><td style="text-align:left;">永久损失才是风险，而非波动</td><td style="text-align:left;">1979</td><td style="text-align:left;">1993, 2003, 2007, 2008</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/look-through-earnings.html">透视盈利 Look-Through Earnings</a></td><td style="text-align:left;">留存收益比股息再投资更合算</td><td style="text-align:left;">1980</td><td style="text-align:left;">1980, 1990, 2004</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/share-buybacks.html">股票回购 Share Buybacks</a></td><td style="text-align:left;">只在股价低于内在价值时回购</td><td style="text-align:left;">1984</td><td style="text-align:left;">1984, 1999, 2011, 2018</td></tr></tbody></table><h2 id="治理智慧-4个核心" tabindex="-1">治理智慧（4个核心） <a class="header-anchor" href="#治理智慧-4个核心" aria-label="Permalink to &quot;治理智慧（4个核心）&quot;">​</a></h2><p>伯克希尔的成功背后是一套独特的治理哲学。选择德才兼备的管理者、设计合理的激励制度、坦诚认错、珍惜声誉——治理是巴菲特投资体系中最被忽视但最关键的环节。</p><table tabindex="0"><thead><tr><th style="text-align:left;">主题</th><th style="text-align:left;">核心要义</th><th style="text-align:left;">首次出现</th><th style="text-align:left;">必读年份</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/02_concepts/management.html">管理层选择 Management</a></td><td style="text-align:left;">找到对的船长，给他们空间</td><td style="text-align:left;">1971</td><td style="text-align:left;">1983, 1995, 2005, 2015</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/executive-compensation.html">高管薪酬 Executive Compensation</a></td><td style="text-align:left;">设计合理的激励，避免股东财富流失</td><td style="text-align:left;">1977</td><td style="text-align:left;">1983, 1992, 2003, 2014</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/mistakes.html">错误坦诚与认错文化</a></td><td style="text-align:left;">公开认错是智慧，不是软弱</td><td style="text-align:left;">1991</td><td style="text-align:left;">1991, 1994, 1997, 2008</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/reputation.html">声誉 Reputation</a></td><td style="text-align:left;">建立需20年，毁掉只需5分钟</td><td style="text-align:left;">1991</td><td style="text-align:left;">1991, 2014, 2020</td></tr></tbody></table><h2 id="投资历史课-5个核心" tabindex="-1">投资历史课（5个核心） <a class="header-anchor" href="#投资历史课-5个核心" aria-label="Permalink to &quot;投资历史课（5个核心）&quot;">​</a></h2><p>巴菲特犯过很多错误，也见证过无数历史。这些教训与案例，是理解巴菲特投资思想最生动的教材。</p><table tabindex="0"><thead><tr><th style="text-align:left;">主题</th><th style="text-align:left;">核心要义</th><th style="text-align:left;">首次出现</th><th style="text-align:left;">必读年份</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/02_concepts/airline-lessons.html">航空公司教训 Airline Mistakes</a></td><td style="text-align:left;">最糟糕的生意模式，反面教材</td><td style="text-align:left;">1989</td><td style="text-align:left;">1989, 1991, 1994, 2007</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/salomon-crisis.html">所罗门兄弟危机 Salomon Crisis</a></td><td style="text-align:left;">正直与勇气，1991年临危受命</td><td style="text-align:left;">1991</td><td style="text-align:left;">1991, 1992</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/japan-investments.html">日本五大投资 Japan Holdings</a></td><td style="text-align:left;">2019-2024年最大非美投资</td><td style="text-align:left;">2019</td><td style="text-align:left;">2020, 2021, 2023, 2024</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/long-term.html">长期主义 Long-term</a></td><td style="text-align:left;">不想持十年就别持十分钟</td><td style="text-align:left;">1966</td><td style="text-align:left;">1996, 2001, 2013, 2020</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/diversification.html">多元化与集中 Diversification</a></td><td style="text-align:left;">分散是对无知的保护</td><td style="text-align:left;">1962</td><td style="text-align:left;">1960, 1996, 2007, 2013</td></tr></tbody></table><h2 id="合伙基金时期-1956-1969-特别专题" tabindex="-1">合伙基金时期（1956-1969）特别专题 <a class="header-anchor" href="#合伙基金时期-1956-1969-特别专题" aria-label="Permalink to &quot;合伙基金时期（1956-1969）特别专题&quot;">​</a></h2><p>巴菲特的<strong>合伙基金时期</strong>（1956-1969）是其投资方法论形成的关键阶段。这14年的许多原则贯穿了他随后的整个投资生涯。</p><table tabindex="0"><thead><tr><th style="text-align:left;">主题</th><th style="text-align:left;">核心要义</th><th style="text-align:left;">必读年份</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/02_concepts/partnership-method.html">三大投资类别体系</a></td><td style="text-align:left;">低估普通股/套利/控股/相对低估的完整体系</td><td style="text-align:left;">1962, 1964, 1969</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/safety-margin.html">安全边际的原始含义</a></td><td style="text-align:left;">买的便宜是硬道理，以低于清算价值的价格买入</td><td style="text-align:left;">1958, 1962, 1964</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/index-benchmark.html">道指为基准</a></td><td style="text-align:left;">三年最低检验周期，主观业绩衡量标准</td><td style="text-align:left;">1962, 1965, 1969</td></tr><tr><td style="text-align:left;"><a href="/02_concepts/risk.html">永久损失 vs 短期波动</a></td><td style="text-align:left;">真正的保守主义是避免永久性资本损失</td><td style="text-align:left;">1966, 1969</td></tr></tbody></table><hr><h2 id="主题关联图" tabindex="-1">主题关联图 <a class="header-anchor" href="#主题关联图" aria-label="Permalink to &quot;主题关联图&quot;">​</a></h2>',24)),(e(),r(x,null,{default:a(()=>[g(d,{id:"mermaid-535",class:"mermaid",graph:"mindmap%0A%20%20root((%E5%B7%B4%E8%8F%B2%E7%89%B9%E6%8A%95%E8%B5%84%E6%80%9D%E6%83%B3))%0A%20%20%20%20%E6%8A%95%E8%B5%84%E5%93%B2%E5%AD%A6%0A%20%20%20%20%20%20%E5%86%85%E5%9C%A8%E4%BB%B7%E5%80%BC%0A%20%20%20%20%20%20%E6%8A%A4%E5%9F%8E%E6%B2%B3%0A%20%20%20%20%20%20%E5%AE%89%E5%85%A8%E8%BE%B9%E9%99%85%0A%20%20%20%20%20%20%E5%A4%8D%E5%88%A9%0A%20%20%20%20%20%20%E7%9C%9F%E5%AE%9E%E7%9B%88%E5%88%A9%0A%20%20%20%20%E5%95%86%E4%B8%9A%E9%80%BB%E8%BE%91%0A%20%20%20%20%20%20%E6%B5%AE%E5%AD%98%E9%87%91%0A%20%20%20%20%20%20%E6%89%BF%E4%BF%9D%E7%BA%AA%E5%BE%8B%0A%20%20%20%20%20%20%E8%B5%84%E6%9C%AC%E9%85%8D%E7%BD%AE%0A%20%20%20%20%20%20%E9%80%92%E5%BB%B6%E7%A8%8E%E5%A4%8D%E5%88%A9%0A%20%20%20%20%E6%8A%95%E8%B5%84%E6%96%B9%E6%B3%95%E8%AE%BA%0A%20%20%20%20%20%20%E8%83%BD%E5%8A%9B%E5%9C%88%0A%20%20%20%20%20%20%E9%80%86%E5%90%91%E6%80%9D%E7%BB%B4%0A%20%20%20%20%20%20%E9%80%8F%E8%A7%86%E7%9B%88%E5%88%A9%0A%20%20%20%20%20%20%E5%9B%9E%E8%B4%AD%E7%BA%AA%E5%BE%8B%0A%20%20%20%20%20%20%E9%A3%8E%E9%99%A9%E5%AE%9A%E4%B9%89%0A%20%20%20%20%E6%B2%BB%E7%90%86%E6%99%BA%E6%85%A7%0A%20%20%20%20%20%20%E7%AE%A1%E7%90%86%E5%B1%82%0A%20%20%20%20%20%20%E8%96%AA%E9%85%AC%E8%AE%BE%E8%AE%A1%0A%20%20%20%20%20%20%E9%94%99%E8%AF%AF%E5%9D%A6%E8%AF%9A%0A%20%20%20%20%20%20%E5%A3%B0%E8%AA%89%0A%20%20%20%20%E5%8E%86%E5%8F%B2%E9%95%9C%E9%89%B4%0A%20%20%20%20%20%20%E8%88%AA%E7%A9%BA%E6%95%99%E8%AE%AD%0A%20%20%20%20%20%20%E6%89%80%E7%BD%97%E9%97%A8%E5%8D%B1%E6%9C%BA%0A%20%20%20%20%20%20%E6%97%A5%E6%9C%AC%E6%8A%95%E8%B5%84%0A%20%20%20%20%20%20%E9%95%BF%E6%9C%9F%E4%B8%BB%E4%B9%89%0A%20%20%20%20%20%20%E5%90%88%E4%BC%99%E5%9F%BA%E9%87%91%E6%96%B9%E6%B3%95%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[f(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<hr><h2 id="_70年主题词频分析-全文翻译统计" tabindex="-1">70年主题词频分析（全文翻译统计） <a class="header-anchor" href="#_70年主题词频分析-全文翻译统计" aria-label="Permalink to &quot;70年主题词频分析（全文翻译统计）&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">主题</th><th style="text-align:left;">最高峰年份</th><th style="text-align:left;">核心讨论期</th><th style="text-align:left;">全程频率</th></tr></thead><tbody><tr><td style="text-align:left;">管理层 CEO</td><td style="text-align:left;">2014年</td><td style="text-align:left;">全程高频</td><td style="text-align:left;">★★★★★</td></tr><tr><td style="text-align:left;">内在价值</td><td style="text-align:left;">2007年</td><td style="text-align:left;">1990s至今</td><td style="text-align:left;">★★★★★</td></tr><tr><td style="text-align:left;">护城河/竞争优势</td><td style="text-align:left;">1993年</td><td style="text-align:left;">1991至今</td><td style="text-align:left;">★★★★★</td></tr><tr><td style="text-align:left;">保险浮存金</td><td style="text-align:left;">2011年</td><td style="text-align:left;">1967至今</td><td style="text-align:left;">★★★★★</td></tr><tr><td style="text-align:left;">收购</td><td style="text-align:left;">2014年</td><td style="text-align:left;">1980s至今</td><td style="text-align:left;">★★★★☆</td></tr><tr><td style="text-align:left;">回购</td><td style="text-align:left;">2018年</td><td style="text-align:left;">2010s爆发</td><td style="text-align:left;">★★★★☆</td></tr><tr><td style="text-align:left;">董事会治理</td><td style="text-align:left;">2002年</td><td style="text-align:left;">2000s爆发</td><td style="text-align:left;">★★★★☆</td></tr><tr><td style="text-align:left;">多元化/集中</td><td style="text-align:left;">2007年</td><td style="text-align:left;">全程</td><td style="text-align:left;">★★★☆☆</td></tr><tr><td style="text-align:left;">航空公司</td><td style="text-align:left;">1994年</td><td style="text-align:left;">1989-2007集中</td><td style="text-align:left;">★★★☆☆</td></tr><tr><td style="text-align:left;">日本投资</td><td style="text-align:left;">2023年</td><td style="text-align:left;">2019-2024</td><td style="text-align:left;">★★★☆☆</td></tr></tbody></table><hr><blockquote><p>💡 <strong>学习建议</strong></p><ol><li><strong>从合伙基金开始</strong>（1956-1969）：理解巴菲特方法的原始逻辑，三大投资类别体系是理解其后期方法的基础</li><li><strong>按顺序阅读</strong>：建议从&quot;投资哲学&quot;五个主题开始，建立完整的价值投资框架</li><li><strong>结合原文</strong>：每个主题都标注了重点年份，建议结合对应年份的股东信全文翻译阅读</li><li><strong>关注治理</strong>：巴菲特晚年越来越强调治理议题，这在2020s变得更加重要</li><li><strong>从错误中学习</strong>：&quot;错误坦诚&quot;专题是理解巴菲特投资逻辑最生动的入口</li></ol></blockquote>',5))])}const _=n(y,[["render",o]]);export{B as __pageData,_ as default};
